<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {Mail,Inbox,Send,PenLine,LogOut,RefreshCw,ArrowRight,ShieldCheck,Check,GraduationCap,Paperclip,Users,Clock3} from '@lucide/vue'
import {auth,request,signIn} from './backend'
import type {ApiResult,OfficeState,ThreadSummary,LetterThread} from './types'
import ScholarPortrait from './components/ScholarPortrait.vue'
import MailOutcome from './components/MailOutcome.vue'
const username=ref('fafa'),password=ref(''),signedIn=ref(false),loading=ref(true),busy=ref(false),error=ref(''),notice=ref('')
const office=ref<OfficeState|null>(null),threads=ref<ThreadSummary[]>([]),thread=ref<LetterThread|null>(null),nextOffset=ref<number|null>(null)
const view=ref<'pending'|'all'|'compose'>('pending'),filterNpc=ref(''),reply=ref(''),offer=ref('none'),to=ref(''),npcId=ref('finance'),subject=ref(''),body=ref(''),studentId=ref('')
const intent=ref<{action:string;payload:Record<string,unknown>;requestId:string}|null>(null)
let timer:ReturnType<typeof setInterval>|undefined
const visible=computed(()=>threads.value.filter(t=>(view.value!=='pending'||t.awaitingStaff)&&(!filterNpc.value||t.npcId===filterNpc.value)))
const selectedPlayer=computed(()=>office.value?.players.find(p=>p.id===to.value))
const pending=computed(()=>threads.value.filter(t=>t.awaitingStaff).length)
const date=(at:number)=>new Date(at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})
function assert(r:ApiResult){if(!r.ok)throw Error(r.error||'未能读取信务室');return r}
async function list(more=false){const r=assert(await request('office_list',{offset:more?nextOffset.value||0:0}));threads.value=more?[...threads.value,...r.threads||[]]:r.threads||[];nextOffset.value=r.nextOffset??null}
async function initialize(){const r=assert(await request('office_state'));office.value=r.office||null;to.value=office.value?.players[0]?.id||'';await list()}
async function login(){busy.value=true;error.value='';try{await signIn(username.value,password.value);password.value='';signedIn.value=true;await initialize()}catch(e){error.value=e instanceof Error?e.message:'登录未完成'}finally{busy.value=false}}
async function logout(){await auth.signOut();signedIn.value=false;office.value=null;thread.value=null;password.value='';error.value=''}
async function open(id:string){
 error.value='';try{const r=assert(await request('office_get',{id}));thread.value=r.thread||null;reply.value='';offer.value='none';if(thread.value?.unread){assert(await request('office_read',{id}));await list()}}catch(e){error.value=e instanceof Error?e.message:'读取失败'}
}
async function mutate(action:string,payload:Record<string,unknown>,retry=false){
 if(busy.value)return;busy.value=true;error.value='';notice.value=''
 const operation=retry&&intent.value?intent.value:{action,payload,requestId:crypto.randomUUID()};intent.value=operation
 sessionStorage.setItem('moyu.office.intent',JSON.stringify(operation))
 try{
  const r=await request(operation.action,operation.payload,operation.requestId)
  if(!r.ok){intent.value=null;sessionStorage.removeItem('moyu.office.intent');throw Error(r.error)}
  intent.value=null;sessionStorage.removeItem('moyu.office.intent');notice.value=r.replayed?'已确认此前投递成功，没有重复发信。':'邮件已保存并投递到游戏邮箱。'
  if(r.thread)thread.value=r.thread;else if(r.threadId){const saved=assert(await request('office_get',{id:r.threadId}));thread.value=saved.thread||null}
  reply.value='';body.value='';subject.value='';offer.value='none';view.value='all';await list()
 }catch(e){error.value=e instanceof Error?e.message:'投递状态待确认，请重试原请求'}finally{busy.value=false}
}
async function refresh(){if(busy.value||!signedIn.value||document.hidden)return;try{if(!office.value)await initialize();else await list();if(thread.value){const r=assert(await request('office_get',{id:thread.value.id}));thread.value=r.thread||thread.value}}catch(e){error.value=e instanceof Error?e.message:'暂时无法同步'}}
onMounted(async()=>{
 try{const raw=sessionStorage.getItem('moyu.office.intent');if(raw){intent.value=JSON.parse(raw);error.value='有一封邮件的投递状态待确认，可以重试原投递。'}const r=await auth.getSession();if(r.data?.session&&!r.data.session.user?.is_anonymous){signedIn.value=true;await initialize()}}catch(e){error.value=e instanceof Error?e.message:'登录状态读取失败'}finally{loading.value=false}
 timer=setInterval(()=>void refresh(),30000)
})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template>
 <div v-if="loading" class="loading-screen"><Mail :size="34"/><h1>正在打开园区信务室</h1></div>
 <main v-else-if="!signedIn" class="office-login"><div class="office-login-story"><span class="office-brand"><Mail :size="25"/>不急大学 · 园区信务室</span><span class="eyebrow">THE STORIES ON THE OTHER SIDE OF THE INBOX</span><h1>他们写了信。<br/><span>故事等你回。</span></h1><p>以学校财务、专利中心或编辑部的身份，<br/>读一封来信，再给两位博士写一封回复。</p><div class="office-envelope"><i/><Mail :size="76" :stroke-width="1"/><span>BUJI UNIVERSITY</span></div><small>独立于游戏的 NPC 邮件工作台。所有内容均为游戏内虚构往来。</small></div><section class="office-login-form"><span class="eyebrow">STAFF ACCESS</span><h2>信务管理员，欢迎。</h2><p>使用 fafa 的游戏账号登录。权限由服务器核验。</p><form @submit.prevent="login"><label>管理员账号<input v-model="username" autocomplete="username" required maxlength="30"/></label><label>四位游戏密码<input v-model="password" type="password" inputmode="numeric" autocomplete="current-password" minlength="4" maxlength="4" required/></label><button class="primary wide" :disabled="busy">{{ busy?'正在核验权限…':'进入园区信务室' }}<ArrowRight :size="17"/></button></form><p v-if="error" class="error-text" role="alert">{{ error }}</p><span class="office-access-note"><ShieldCheck :size="16"/>Yizi 的玩家账号不能操作 NPC 信务。</span></section></main>
 <div v-else class="office-shell"><header class="office-header"><span class="office-brand"><Mail :size="23"/><b>园区信务室</b><small>BUJI UNIVERSITY · NPC MAILROOM</small></span><div><span>仅游戏内邮件</span><button class="icon-button" aria-label="刷新信务室" :disabled="busy" @click="refresh"><RefreshCw :size="17"/></button><button class="icon-button" aria-label="退出信务室" :disabled="busy" @click="logout"><LogOut :size="18"/></button></div></header>
  <div v-if="error" class="status-banner error-banner" role="alert"><span>{{ error }}</span><button v-if="intent" :disabled="busy" @click="mutate(intent.action,intent.payload,true)">重试原投递</button></div><div v-if="notice" class="status-banner success-banner"><Check :size="16"/>{{ notice }}</div>
  <div v-if="!office" class="office-denied"><ShieldCheck :size="38"/><h1>当前账号没有信务室权限</h1><p>请退出后使用 fafa 账号登录。游戏玩家权限不会自动变成 NPC 管理权限。</p><button class="primary" @click="logout">切换账号</button></div>
  <div v-else class="office-workspace"><aside class="office-sidebar"><span class="eyebrow">NPC CORRESPONDENCE</span><button class="primary wide" @click="view='compose';offer='none';thread=null"><PenLine :size="17"/>以 NPC 身份发信</button><nav><button :class="{active:view==='pending'}" @click="view='pending'"><Inbox :size="17"/>待我回复<b>{{ pending }}</b></button><button :class="{active:view==='all'}" @click="view='all'"><Mail :size="17"/>全部往来</button></nav><span class="office-side-caption">发件部门</span><button class="office-department" :class="{active:!filterNpc}" @click="filterNpc=''">所有部门</button><button v-for="c in office.contacts" :key="c.id" class="office-department" :class="[c.color,{active:filterNpc===c.id}]" @click="filterNpc=c.id;view='all'"><i/>{{ c.name }}</button><div class="office-player-list"><span>园区里的两位博士</span><article v-for="p in office.players" :key="p.id"><ScholarPortrait :seed="p.id" :size="34" :label="p.name+'头像'"/><div><b>{{ p.name }}</b><small>{{ p.discipline==='air'?'低空经济':'智能建造' }}</small></div></article></div><p class="office-boundary">只处理发给 NPC 的会话；玩家间的私人往来不进入此工作台。</p></aside>
   <section v-if="view==='compose'" class="office-main office-composer"><span class="eyebrow">A NEW LETTER FROM CAMPUS</span><h1>写一封新的来信</h1><form @submit.prevent="mutate('office_send',{to,npcId,subject,body,offer,studentId:studentId||undefined})"><div class="office-compose-row"><label>发件 NPC<select v-model="npcId"><option v-for="c in office.contacts" :key="c.id" :value="c.id">{{ c.name }} · {{ c.address }}</option></select></label><label>收件玩家<select v-model="to" @change="studentId=''"><option v-for="p in office.players" :key="p.id" :value="p.id">{{ p.name }}</option></select></label></div><label>主题<input v-model="subject" maxlength="120" required placeholder="例如：邀请贵组参加青年学者报告会"/></label><label>邮件正文<textarea v-model="body" rows="11" maxlength="4000" required placeholder="老师您好：&#10;&#10;我们诚邀贵组……"/></label><div class="office-compose-row"><label>可选互动邀请<select v-model="offer"><option value="none">普通邮件，只发送正文</option><option value="conference">学术会议（玩家选择后揭晓结果）</option><option value="visit">学生访学（120 经费、12 小时）</option></select></label><label>建议参与学生（可选）<select v-model="studentId"><option value="">由收件人自己安排</option><option v-for="st in selectedPlayer?.students||[]" :key="st.id" :value="st.id">{{ st.name }} · {{ st.topic }}</option></select></label></div><p class="office-help">正文不会自动变成奖励指令。选择互动邀请后，服务器会提供对应选项并在玩家选择时结算。</p><button class="primary" :disabled="busy||!to||!subject.trim()||!body.trim()"><Send :size="17"/>发送到游戏邮箱</button></form></section>
   <template v-else><section class="office-thread-list"><div class="office-list-title"><h2>{{ view==='pending'?'等你回复的来信':'园区邮件往来' }}</h2><small>{{ visible.length }} 段会话</small></div><button v-for="t in visible" :key="t.id" :class="{selected:thread?.id===t.id,unread:t.awaitingStaff}" @click="open(t.id)"><span><b>{{ t.participants?.map(id=>office!.players.find(p=>p.id===id)?.name).join('、') }}</b><time>{{ date(t.updatedAt) }}</time></span><strong>{{ t.subject }}</strong><small>{{ office.contacts.find(c=>c.id===t.npcId)?.name }} · {{ t.awaitingStaff?'待回复':'已投递' }}</small><p>{{ t.last?.body.slice(0,70) }}</p></button><div v-if="!visible.length" class="office-empty-list"><Inbox :size="30"/><p>暂时没有这类来信。<br/>玩家给 NPC 发信后，会出现在这里。</p></div><button v-if="nextOffset!==null" class="text-button" @click="list(true)">读取更早的会话</button></section>
    <section class="office-main"><template v-if="thread"><span class="eyebrow">CAMPUS MAIL · {{ thread.id.slice(0,8) }}</span><h1>{{ thread.subject }}</h1><p class="office-correspondents">{{ office.contacts.find(c=>c.id===thread!.npcId)?.name }} ↔ {{ thread.participants.map(id=>office!.players.find(p=>p.id===id)?.name).join('、') }}</p><div v-if="thread.attachedStudent" class="student-attachment"><Paperclip :size="15"/>{{ thread.attachedStudent.name }} · {{ thread.attachedStudent.topic }}</div><div class="conversation-messages office-conversation"><section v-for="m in thread.messages" :key="m.id" :class="{mine:m.role==='npc',receipt:m.role==='receipt'}"><div><b>{{ m.fromName }}</b><time>{{ date(m.at) }}</time></div><small>{{ m.fromAddress }}</small><p>{{ m.body }}</p></section></div><MailOutcome v-if="thread.offer?.repliedAt" :mail="thread.offer"/><form class="office-reply" @submit.prevent="mutate('office_reply',{id:thread!.id,body:reply,offer})"><label>以 {{ office.contacts.find(c=>c.id===thread!.npcId)?.name }} 的身份回复<textarea v-model="reply" rows="7" maxlength="4000" required placeholder="写下 NPC 实际要说的话，不要替玩家做心理描写。"/></label><label>附带互动邀请<select v-model="offer"><option value="none">不添加，普通回复</option><option value="conference" :disabled="!!thread.offer&&!thread.offer.repliedAt">学术会议邀请</option><option value="visit" :disabled="!!thread.offer&&!thread.offer.repliedAt">学生访学邀请</option></select></label><div><span>会话保存到服务器，玩家下次同步就能收到。</span><button class="primary" :disabled="busy||!reply.trim()"><Send :size="16"/>投递回复</button></div></form></template><div v-else class="office-open-prompt"><Mail :size="53" :stroke-width="1.2"/><h2>打开一封信，让故事接着走。</h2><p>可以回复报销、专利、投稿或合作咨询，<br/>也可以主动写一封学术邀请。</p></div></section></template>
  </div>
 </div>
</template>
